	private String repeatedVariableBody(int roots) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI firstPredicate = vf.createIRI(EX, "repeatedSelectFirst");
			IRI secondPredicate = vf.createIRI(EX, "repeatedSelectSecond");
			IRI repeatedPredicate = vf.createIRI(EX, "repeatedSelectRepeated");
			connection.begin();
			for (int i = 0; i < roots; i++) {
				IRI subject = vf.createIRI(EX, "repeatedSelect/subject/" + i);
				IRI middle = vf.createIRI(EX, "repeatedSelect/middle/" + i);
				IRI value = vf.createIRI(EX, "repeatedSelect/value/" + i);
				connection.add(subject, firstPredicate, middle);
				connection.add(middle, secondPredicate, value);
				connection.add(value, repeatedPredicate, value);
				connection.add(value, repeatedPredicate, vf.createIRI(EX, "repeatedSelect/unequal/" + i));
				connection.add(value, vf.createIRI(EX, "repeatedSelectWitness"), value);
				connection.add(vf.createIRI(EX, "repeatedSelect/noise/" + i), repeatedPredicate,
						vf.createIRI(EX, "repeatedSelect/noise/" + i));
			}
			connection.commit();
		}

		return "?subject <" + EX + "repeatedSelectFirst> ?middle . "
				+ "?middle <" + EX + "repeatedSelectSecond> ?value . "
				+ "?value <" + EX + "repeatedSelectRepeated> ?value . ";
	}

	@Test
	public void repeatedSlotSuffixUsesExternalRootChunkWhenRowFactorizationRefuses() throws Exception {
		long[][] quads = {
				{ 1L, 7L, 8L, 0L },
				{ 2L, 7L, 8L, 0L },
				{ 1L, 9L, 101L, 0L },
				{ 2L, 9L, 202L, 0L },
				{ 101L, 10L, 101L, 0L },
				{ 202L, 10L, 202L, 0L },
				{ 101L, 10L, 999L, 0L }
		};
		RepeatedSlotSource source = new RepeatedSlotSource(quads);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("subject", 0, "value", 1), null);
		layout.freeze(List.of("subject", "value"));
		PatternPlan root = new PatternPlan(Term.slot(0), Term.constant(7), Term.constant(8), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 1D);
		PatternPlan middle = new PatternPlan(Term.slot(0), Term.constant(9), Term.slot(1), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 10D);
		PatternPlan repeatedSuffix = new PatternPlan(Term.slot(1), Term.constant(10), Term.slot(1), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 100D);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { root, middle, repeatedSuffix }, new MaskedFilter[0]);
		RowState planningRow = emptyNativeRow(source, layout);
		MultiJoinPlan.OrderedPlan derived = plan.derivedFactorizedPlan(planningRow);
		assertThat(derived.order[0]).isSameAs(root);
		assertThat(LmdbNativeFactorizedRows.tryCreateFromExternalRoot(plan, derived, planningRow,
				planningRow.boundMask(), new int[] { 0, 1 }, false))
						.as("the repeated-slot suffix is deliberately outside flat-bag factorization")
						.isNull();

		RowState sequentialRow = emptyNativeRow(source, layout);
		List<String> sequential = readNativeRows(plan.open(sequentialRow), sequentialRow);
		NativeRowsStep step = new NativeRowsStep(source, plan, layout, new int[] { 0, 1 },
				new String[] { "subject", "value" }, false, new int[0], new boolean[0], 0L, -1L, false, null,
				null, null, Set.of(), null, null);
		RowState parallelRow = emptyNativeRow(source, layout);
		long parallelBefore = LmdbNativeParallelPipelines.PARALLEL_ROW_RUNS.get();
		long chunkBefore = LmdbNativeChunkPipeline.ENGAGED.get();
		long factorizedBefore = LmdbNativeFactorizedRows.ENGAGED.get();
		RowCursor parallelCursor = LmdbNativeParallelPipelines.tryOpen(step, parallelRow);
		assertThat(parallelCursor)
				.as("parallel rejection: %s", LmdbNativeParallelPipelines.LAST_REJECTION.get())
				.isNotNull();
		List<String> parallel = readNativeRows(parallelCursor, parallelRow);

		assertThat(parallel).containsExactlyElementsOf(sequential).containsExactly("1|101", "2|202");
		assertThat(LmdbNativeParallelPipelines.PARALLEL_ROW_RUNS.get()).isEqualTo(parallelBefore + 1L);
		assertThat(LmdbNativeChunkPipeline.ENGAGED.get())
				.as("workers must try the external-root chunk chain after row-factorization refusal")
				.isGreaterThan(chunkBefore);
		assertThat(LmdbNativeFactorizedRows.ENGAGED.get())
				.as("the repeated-slot suffix must not be reported as a factorized-row attempt")
				.isEqualTo(factorizedBefore);
	}

	@Test
	public void planLevelWorkAdmitsFanoutAndRejectsDeadTail() throws Exception {
		String previousWorkThreshold = System.clearProperty(WORK_THRESHOLD_FLAG);
		try {
			NativeSlotLayout layout = twoSlotLayout();
			PatternPlan highFanoutRoot = pattern(Term.slot(0), 7L, Term.constant(8L), 8_000D);
			PatternPlan highFanoutTail = pattern(Term.slot(0), 9L, Term.slot(1), 100D);
			RepeatedSlotSource highFanoutSource = new RepeatedSlotSource(new long[0][], Map.of(9L, 100D));
			MultiJoinPlan highFanoutPlan = new MultiJoinPlan(
					new SlotPlan[] { highFanoutRoot, highFanoutTail }, new MaskedFilter[0]);
			RowState highFanoutRow = emptyNativeRow(highFanoutSource, layout);

			assertThat(highFanoutRoot.estimate(highFanoutRow)).isEqualTo(8_000D);
			assertThat(highFanoutPlan.estimate(highFanoutRow)).isEqualTo(800_000D);
			LmdbNativeStrategyProposal<RowCursor> highFanout = LmdbNativeParallelPipelines
					.propose(nativeStep(highFanoutSource, highFanoutPlan, layout), highFanoutRow);
			assertThat(highFanout)
					.as("8k root with 100x measured downstream fan-out must clear work-based admission")
					.isNotNull();
			highFanout.close();

			PatternPlan deadRoot = pattern(Term.slot(0), 7L, Term.constant(8L), 60_000D);
			PatternPlan deadTail = pattern(Term.slot(0), 10L, Term.slot(1), 1D);
			RepeatedSlotSource deadSource = new RepeatedSlotSource(new long[0][], Map.of(10L, 0D));
			MultiJoinPlan deadPlan = new MultiJoinPlan(new SlotPlan[] { deadRoot, deadTail }, new MaskedFilter[0]);
			RowState deadRow = emptyNativeRow(deadSource, layout);

			assertThat(deadRoot.estimate(deadRow)).isEqualTo(60_000D);
			assertThat(deadPlan.estimate(deadRow)).isZero();
			LmdbNativeStrategyProposal<RowCursor> dead = LmdbNativeParallelPipelines
					.propose(nativeStep(deadSource, deadPlan, layout), deadRow);
			try {
				assertThat(dead)
						.as("a large root whose measured suffix has no work must stay sequential")
						.isNull();
				assertThat(LmdbNativeParallelPipelines.LAST_REJECTION.get()).isEqualTo("below-threshold");
			} finally {
				if (dead != null) {
					dead.close();
				}
			}
		} finally {
			restoreProperty(WORK_THRESHOLD_FLAG, previousWorkThreshold);
		}
	}

	@ParameterizedTest
	@CsvSource({ ", 2047, false", ", 2048, true", ", 3072, true", ", 4096, true",
			"invalid, 2048, true", "NaN, 2048, true", "Infinity, 2048, true", "-1, 2048, true",
			"4096, 3072, false", "4096, 4096, true", "0, 1, true" })
	void parallelAdmissionUsesHalvedDefaultAndHonorsOverrides(String configured, double work, boolean admitted)
			throws Exception {
		String previous = System.getProperty(WORK_THRESHOLD_FLAG);
		try {
			restoreProperty(WORK_THRESHOLD_FLAG, configured);
			NativeSlotLayout layout = twoSlotLayout();
			RepeatedSlotSource source = new RepeatedSlotSource(new long[0][], Map.of(9L, 1D));
			MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] {
					pattern(Term.slot(0), 7L, Term.constant(8L), work),
					pattern(Term.slot(0), 9L, Term.slot(1), 1D) }, new MaskedFilter[0]);
			RowState row = emptyNativeRow(source, layout);
			assertThat(plan.estimate(row)).isEqualTo(work);
			try (var proposal = LmdbNativeParallelPipelines.propose(nativeStep(source, plan, layout), row)) {
				assertThat(proposal != null).isEqualTo(admitted);
				if (!admitted) {
					assertThat(LmdbNativeParallelPipelines.LAST_REJECTION.get()).isEqualTo("below-threshold");
				}
			}
		} finally {
			restoreProperty(WORK_THRESHOLD_FLAG, previous);
		}
	}

